// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const dados = $input.first().json;
const clientes = dados.body?.clientes ?? [];
const investimentos = dados.investimentos ?? [];

// ---------- helpers ----------
const norm = (s) =>
  String(s ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();

const parseSaldo = (t) => {
  const limpo = String(t ?? "").replace(/[^\d,.-]/g, "");
  const n = Number(limpo.replace(/\./g, "").replace(",", "."));
  return Number.isNaN(n) ? 0 : n;
};

const brl = (n) =>
  "R$ " + n.toFixed(2).replace(".", ",").replace(/\B(?=(\d{3})+(?!\d))/g, ".");

const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

// ordem de risco, usada no fallback
const ordem = ["conservador", "moderado", "arrojado"];

// ---------- processamento ----------
const resultados = clientes.map((c) => {
  const saldoNum = parseSaldo(c.saldo);
  const perfilCli = norm(c.perfil);
  const idxPerfil = ordem.indexOf(perfilCli);

  // investimentos que o saldo cobre
  const acessiveis = investimentos.filter((i) => i.minimo <= saldoNum);

  // 1) ideal: mesmo perfil do cliente, o de maior mínimo que ele alcança
  let candidatos = acessiveis
    .filter((i) => norm(i.perfil) === perfilCli)
    .sort((a, b) => b.minimo - a.minimo);

  let motivo;
  let escolhido = candidatos[0] ?? null;

  if (escolhido) {
    motivo = `Perfil ${c.perfil} e saldo de ${brl(saldoNum)} cobrem o mínimo de ${brl(escolhido.minimo)}.`;
  } else {
    // 2) fallback: perfis mais conservadores que o do cliente
    const fallback = acessiveis
      .filter((i) => ordem.indexOf(norm(i.perfil)) < idxPerfil)
      .sort((a, b) => b.minimo - a.minimo);
    escolhido = fallback[0] ?? null;

    motivo = escolhido
      ? `Saldo de ${brl(saldoNum)} não alcança o mínimo dos produtos ${c.perfil}; sugerida opção mais conservadora.`
      : `Saldo de ${brl(saldoNum)} abaixo do mínimo de todos os investimentos disponíveis.`;
  }

  const produto = escolhido?.produto ?? "";
  const rent = escolhido?.rentabilidade ?? "";

  const mensagens = escolhido
    ? [
        `Olá, ${c.nome}! Com base no seu perfil ${c.perfil}, uma boa opção para você é ${produto} (rentabilidade: ${rent}).`,
        `${c.nome}, analisamos seu saldo de ${brl(saldoNum)} e separamos ${produto} para você. Rentabilidade: ${rent}.`,
        `Oi, ${c.nome}! ${produto} combina com seu perfil ${c.perfil} e cabe no seu saldo. Rentabilidade: ${rent}.`,
      ]
    : [
        `Olá, ${c.nome}! No momento nenhum investimento se encaixa no seu saldo atual. Assim que ele crescer, avisamos!`,
        `${c.nome}, ainda não temos uma opção ideal para seu saldo de ${brl(saldoNum)}. Vamos te avisar quando houver.`,
      ];

  return {
    nome: c.nome,
    email: c.email,
    perfil: c.perfil,
    saldo_texto: c.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens),
  };
});

// 1 item por cliente (o Gemini roda 1x para cada)
return resultados.map((r) => ({
  json: {
    ...r,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
  },
}));

