// ===== CONFIG =====
const MODO_TESTE = true; // true = manda tudo pro seu e-mail | false = envia pros clientes
const EMAIL_TESTE = 'COLOQUE_SEU_EMAIL_AQUI'; // usado só quando MODO_TESTE = true

const DOMINIOS_BLOQUEADOS = ['example.com', 'example.org', 'teste.com', 'test.com', 'exemplo.com'];
const DOMINIOS_TYPO = {
  'gmial.com': 'gmail.com', 'gmai.com': 'gmail.com', 'gmil.com': 'gmail.com',
  'gmail.con': 'gmail.com', 'gmail.com.br': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmail.con': 'hotmail.com',
  'outlok.com': 'outlook.com', 'yaho.com': 'yahoo.com', 'yahoo.con': 'yahoo.com',
};

// ===== VALIDAÇÃO DE E-MAIL =====
const validarEmail = (bruto) => {
  const email = String(bruto ?? '').trim().toLowerCase();
  const falha = (motivo) => ({ valido: false, email, motivo });

  if (!email) return falha('e-mail vazio');
  if (email.length > 254) return falha('e-mail longo demais');

  const partes = email.split('@');
  if (partes.length !== 2) return falha('precisa ter exatamente um @');

  const [local, dominio] = partes;
  if (!local || local.length > 64) return falha('parte antes do @ vazia ou longa demais');
  if (!/^[a-z0-9._%+\-]+$/.test(local)) return falha('caracteres inválidos antes do @');
  if (local.startsWith('.') || local.endsWith('.') || local.includes('..')) return falha('pontos mal posicionados antes do @');

  if (!/^[a-z0-9.\-]+$/.test(dominio)) return falha('domínio com caracteres inválidos');
  const labels = dominio.split('.');
  if (labels.length < 2 || labels.some((l) => !l || l.startsWith('-') || l.endsWith('-'))) return falha('domínio inválido');
  if (!/^[a-z]{2,}$/.test(labels[labels.length - 1])) return falha('extensão do domínio inválida');

  if (DOMINIOS_BLOQUEADOS.includes(dominio)) return falha('domínio de teste/exemplo');
  if (DOMINIOS_TYPO[dominio]) return falha(`possível erro de digitação (quis dizer @${DOMINIOS_TYPO[dominio]}?)`);

  return { valido: true, email, motivo: null };
};

// ===== LEITURA DA RESPOSTA DO GEMINI =====
const lerJson = (t) => {
  const limpo = String(t ?? '').replace(/```json|```/gi, '').trim();
  try {
    return JSON.parse(limpo);
  } catch {
    const m = limpo.match(/\{[\s\S]*\}/);
    if (m) {
      try { return JSON.parse(m[0]); } catch {}
    }
    return null;
  }
};

// casa cada resposta do Gemini com o cliente de origem
const origem = $('Criar mensagens personalizadas');
const pegarOriginal = (i) => {
  try { return origem.itemMatching(i).json; }
  catch { return origem.all()[i].json; }
};

return $input.all().map((item, i) => {
  const j = pegarOriginal(i);
  const texto =
    item.json?.content?.parts?.[0]?.text ??
    item.json?.candidates?.[0]?.content?.parts?.[0]?.text ??
    '';
  const parsed = lerJson(texto);

  const real = validarEmail(j.email);
  const teste = MODO_TESTE ? validarEmail(EMAIL_TESTE) : null;
  const email_valido = real.valido && (!MODO_TESTE || teste.valido);
  const motivo_email = !real.valido
    ? real.motivo
    : (MODO_TESTE && !teste.valido ? 'EMAIL_TESTE não configurado' : null);

  const to = MODO_TESTE ? teste.email : real.email;

  const subjectBase = parsed?.subject ?? `Sugestão de investimento para ${j.nome}`;
  const subject = MODO_TESTE ? `[TESTE → ${real.email || j.email}] ${subjectBase}` : subjectBase;
  const text_body = parsed?.text_body ?? j.mensagem_escolhida;
  const html_body =
    parsed?.html_body ?? `<p>${String(text_body).replace(/\n/g, '<br>')}</p>`;

  return {
    json: {
      ok: !!parsed,
      email_valido,
      motivo_email,
      modo_teste: MODO_TESTE,
      to,
      to_original: real.email,
      subject,
      text_body,
      html_body,
      meta: {
        nome: j.nome,
        perfil: j.perfil,
        produto: j.recomendacao?.produto,
        minimo: j.recomendacao?.minimo,
        rentabilidade: j.recomendacao?.rentabilidade,
        motivo: j.motivo,
      },
    },
  };
});

const seguro = (fn) => { try { return fn(); } catch { return []; } };

const todos = seguro(() => $('Normalizar certas regras').all()).map((i) => i.json);
const gmail = seguro(() => $('Send a message').all()).map((i) => i.json);

const validos = todos.filter((t) => t.email_valido);
const invalidos = todos.filter((t) => !t.email_valido);

const txtErro = (e) =>
  !e ? 'sem resposta do Gmail' : (typeof e === 'object' ? (e.message ?? JSON.stringify(e)) : String(e));

// o Gmail processa os válidos na mesma ordem
const detalhes = validos.map((t, i) => {
  const g = gmail[i];
  const enviado = !!(g && g.id && !g.error);
  return {
    nome: t.meta?.nome,
    para: t.to,
    cliente: t.to_original,
    status: enviado ? 'enviado' : 'falha_no_envio',
    erro: enviado ? null : txtErro(g?.error),
    ia_ok: t.ok,
  };
});

invalidos.forEach((t) => {
  detalhes.push({
    nome: t.meta?.nome,
    para: null,
    cliente: t.to_original,
    status: 'email_invalido',
    erro: t.motivo_email,
    ia_ok: t.ok,
  });
});

return [{
  json: {
    ok: true,
    modo_teste: todos[0]?.modo_teste ?? null,
    total: todos.length,
    enviados: detalhes.filter((d) => d.status === 'enviado').length,
    falhas_no_envio: detalhes.filter((d) => d.status === 'falha_no_envio').length,
    emails_invalidos: invalidos.length,
    detalhes,
  },
}];
